  .face-0 {     transform: rotateX(0deg) translateZ(71px);   }   .face-1 {     transform: rotateX(-36deg) translateZ(71px);   }   .face-2 {     transform: rotateX(-72deg) translateZ(71px);   }   .face-3 {     transform: rotateX(-108deg) translateZ(71px);   }   .face-4 {     transform: rotateX(-144deg) translateZ(71px);   }   .face-5 {     transform: rotateX(-180deg) translateZ(71px);   }   .face-6 {     transform: rotateX(-216deg) translateZ(71px);   }   .face-7 {     transform: rotateX(-252deg) translateZ(71px);   }   .face-8 {     transform: rotateX(-288deg) translateZ(71px);   }   .face-9 {     transform: rotateX(-324deg) translateZ(71px);   }

